const items = $input.all();

if (items.length === 0) {
  throw new Error("CSV contains no records.");
}

// Remove PAYMENT_METHOD and rename FINAL REVENUE
// to match the existing MySQL column FINAL_REVENUE.

const output = items.map(item => {
  const row = { ...item.json };

  // Remove the duplicate payment-method column
  delete row.PAYMENT_METHOD;
  delete row.IS_CANCELED;

  // Map CSV column name to MySQL column name
  if ("FINAL REVENUE" in row) {
    row.FINAL_REVENUE = row["FINAL REVENUE"];
    delete row["FINAL REVENUE"];
  }

  return {
    json: row
  };
});

return output;

